=== FILE: rr_arbiter.v ===
`timescale 1ns/1ps
`default_nettype none

// rr_arbiter: round-robin arbiter, N requesters, at most one grant per cycle.
// Implements interface_spec.md / microarchitecture.md (rtl/rr-arbiter).
// State: one priority pointer ptr ($clog2(N) bits), synchronous active-low
// reset to 0. grant is combinational from req and ptr. On a rising edge with
// a grant, ptr moves to one past the winner, wrapping from N-1 to 0 against N
// (not at a power of two). With no request, ptr holds.
module rr_arbiter #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    output reg  [N-1:0] grant
);

    localparam integer PW = (N > 1) ? $clog2(N) : 1;

    reg  [PW-1:0] ptr;
    reg  [PW-1:0] ptr_nxt;
    reg  [N-1:0]  mask;
    reg           seen;
    reg           found;
    integer       k;
    integer       i;

    // Index of the requester after idx, wrapping from N-1 to 0.
    function [PW-1:0] nxt_idx(input integer idx);
        integer t;
        begin
            nxt_idx = {PW{1'b0}};
            for (t = 0; t < N; t = t + 1) begin
                if (t == idx + 1) begin
                    nxt_idx = t[PW-1:0];
                end
            end
        end
    endfunction

    // mask[k] is high for every requester at or after the pointer.
    always @* begin
        mask = {N{1'b0}};
        seen = 1'b0;
        for (k = 0; k < N; k = k + 1) begin
            if (ptr == k[PW-1:0]) begin
                seen = 1'b1;
            end
            mask[k] = seen;
        end
    end

    // Wrapping priority search: first the requesters at or after the
    // pointer, then (the wrap) all requesters from 0. The first one found
    // wins; its successor index is the next pointer.
    always @* begin
        grant   = {N{1'b0}};
        ptr_nxt = ptr;
        found   = 1'b0;
        for (i = 0; i < N; i = i + 1) begin
            if (!found && mask[i] && req[i]) begin
                grant[i] = 1'b1;
                found    = 1'b1;
                ptr_nxt  = nxt_idx(i);
            end
        end
        for (i = 0; i < N; i = i + 1) begin
            if (!found && req[i]) begin
                grant[i] = 1'b1;
                found    = 1'b1;
                ptr_nxt  = nxt_idx(i);
            end
        end
    end

    // Pointer register: reset value, otherwise the computed next value.
    always @(posedge clk) begin
        if (!rst_n) begin
            ptr <= {PW{1'b0}};
        end else begin
            ptr <= ptr_nxt;
        end
    end

`ifdef FORMAL
    // Design-intent properties (interface_spec.md section 6).
    localparam [PW-1:0] F_LAST = N - 1;

    reg     f_past_valid = 1'b0;
    integer f_p;
    integer f_win;
    integer f_nxt;
    integer f_dw;
    integer f_i;

    always @(posedge clk) begin
        f_past_valid <= 1'b1;
    end

    always @(*) begin
        if (!f_past_valid) begin
            assume (!rst_n);
        end
    end

    // Winner index, its successor, and its distance from the pointer.
    always @(*) begin
        f_p   = ptr;
        f_win = 0;
        for (f_i = 0; f_i < N; f_i = f_i + 1) begin
            if (grant[f_i]) begin
                f_win = f_i;
            end
        end
        f_nxt = (f_win == N - 1) ? 0 : (f_win + 1);
        f_dw  = (f_win >= f_p) ? (f_win - f_p) : (f_win + N - f_p);
    end

    always @(*) begin
        assert ((grant & (grant - {{(N-1){1'b0}}, 1'b1})) == {N{1'b0}});
        assert ((grant & ~req) == {N{1'b0}});
        if (req != {N{1'b0}}) begin
            assert (grant != {N{1'b0}});
        end
        if (f_past_valid) begin
            assert (f_p < N);
        end
    end

    always @(posedge clk) begin
        if (f_past_valid && !$past(rst_n)) begin
            assert (ptr == {PW{1'b0}});
        end
        if (f_past_valid && $past(rst_n)) begin
            if ($past(grant) == {N{1'b0}}) begin
                assert (ptr == $past(ptr));
            end else begin
                assert (f_p == $past(f_nxt));
            end
        end
    end

    genvar gi;
    generate
        for (gi = 0; gi < N; gi = gi + 1) begin : g_fv
            reg [7:0] f_wait = 8'd0;
            integer   f_di;

            always @(posedge clk) begin
                if (!rst_n || !req[gi] || grant[gi]) begin
                    f_wait <= 8'd0;
                end else begin
                    f_wait <= f_wait + 8'd1;
                end
            end

            always @(*) begin
                f_di = (gi >= f_p) ? (gi - f_p) : (gi + N - f_p);
                if (f_past_valid) begin
                    // No requester sits between the pointer and the winner.
                    if (req[gi] && (grant != {N{1'b0}})) begin
                        assert (f_di >= f_dw);
                    end
                    assert (f_wait <= N - 1);
                    if (f_wait != 8'd0) begin
                        assert (f_wait + f_di <= N - 1);
                    end
                end
                cover (f_past_valid && rst_n && grant[gi]);
                cover (f_past_valid && (f_wait == N - 1));
            end
        end
    endgenerate

    always @(*) begin
        cover (f_past_valid && rst_n && (req == {N{1'b1}}));
    end

    always @(posedge clk) begin
        cover (f_past_valid && $past(rst_n) && ($past(ptr) == F_LAST)
               && (ptr == {PW{1'b0}}));
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
