`timescale 1ns/1ps
`default_nettype none

// Self-checking testbench for rr_arbiter (interface_spec.md section 6):
// two arbiters side by side, N 4 and N 5, each checked every rising edge
// against an independent reference pointer model, with per-requester wait
// counters and coverage flags that fail the run if a case was not reached.

module rr_arbiter_tb_unit #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    input  wire         final_check,
    output wire [31:0]  passed,
    output wire [31:0]  failed
);

    wire [N-1:0] grant;

    rr_arbiter #(.N(N)) dut (
        .clk   (clk),
        .rst_n (rst_n),
        .req   (req),
        .grant (grant)
    );

    integer     npass      = 0;
    integer     nfail      = 0;
    integer     cyc        = 0;
    integer     mptr       = 0;
    reg         started    = 1'b0;
    reg         final_done = 1'b0;
    reg         prev_valid = 1'b0;
    reg         prev_rst_n = 1'b0;
    reg [N-1:0] prev_req   = {N{1'b0}};
    reg [N-1:0] eg         = {N{1'b0}};
    reg         seen_none  = 1'b0;
    reg         seen_all   = 1'b0;
    reg         seen_held  = 1'b0;
    reg         seen_long  = 1'b0;
    reg         seen_rst   = 1'b0;
    reg [N-1:0] seen_alone = {N{1'b0}};
    integer     wt [0:N-1];
    integer     r;
    integer     t;

    assign passed = npass;
    assign failed = nfail;

    function integer popcnt(input [N-1:0] vec);
        integer b;
        begin
            popcnt = 0;
            for (b = 0; b < N; b = b + 1) begin
                if (vec[b]) begin
                    popcnt = popcnt + 1;
                end
            end
        end
    endfunction

    // Reference: the first requester at or after pointer p, by modular index.
    function [N-1:0] exp_grant(input [N-1:0] rq, input integer p);
        integer off;
        integer b;
        reg     hit;
        begin
            exp_grant = {N{1'b0}};
            hit = 1'b0;
            for (off = 0; off < N; off = off + 1) begin
                for (b = 0; b < N; b = b + 1) begin
                    if (!hit && (b == ((p + off) % N)) && rq[b]) begin
                        exp_grant[b] = 1'b1;
                        hit = 1'b1;
                    end
                end
            end
        end
    endfunction

    always @(posedge clk) begin
        cyc = cyc + 1;
        eg  = exp_grant(req, mptr);

        if (started) begin
            // Round-robin order against the reference pointer model.
            if (grant !== eg) begin
                $error("rr_arbiter N=%0d cycle %0d: grant %b, expected %b (req %b, model pointer %0d)",
                       N, cyc, grant, eg, req, mptr);
                nfail = nfail + 1;
            end else begin
                npass = npass + 1;
            end
            // One grant at most.
            if (popcnt(grant) > 1) begin
                $error("rr_arbiter N=%0d cycle %0d: grant %b is not one-hot or zero", N, cyc, grant);
                nfail = nfail + 1;
            end else begin
                npass = npass + 1;
            end
            // Grant only to a requester.
            if ((grant & ~req) != {N{1'b0}}) begin
                $error("rr_arbiter N=%0d cycle %0d: grant %b to a non-requester (req %b)", N, cyc, grant, req);
                nfail = nfail + 1;
            end else begin
                npass = npass + 1;
            end
            // Work conserving.
            if ((req != {N{1'b0}}) && (grant == {N{1'b0}})) begin
                $error("rr_arbiter N=%0d cycle %0d: req %b but no grant", N, cyc, req);
                nfail = nfail + 1;
            end else begin
                npass = npass + 1;
            end

            if (rst_n) begin
                // Fairness: a held request waits at most N-1 cycles.
                for (r = 0; r < N; r = r + 1) begin
                    if (req[r] && !grant[r]) begin
                        wt[r] = wt[r] + 1;
                        if (wt[r] > N - 1) begin
                            $error("rr_arbiter N=%0d cycle %0d: requester %0d has waited %0d cycles",
                                   N, cyc, r, wt[r]);
                            nfail = nfail + 1;
                        end else begin
                            npass = npass + 1;
                        end
                        if (wt[r] == N - 1) begin
                            seen_long = 1'b1;
                        end
                    end else begin
                        wt[r] = 0;
                    end
                end
                // Coverage.
                if (req == {N{1'b0}}) begin
                    seen_none = 1'b1;
                end
                if (req == {N{1'b1}}) begin
                    seen_all = 1'b1;
                end
                for (r = 0; r < N; r = r + 1) begin
                    if ((popcnt(req) == 1) && req[r] && grant[r]) begin
                        seen_alone[r] = 1'b1;
                    end
                    if (prev_valid && req[r] && prev_req[r] && (req != prev_req)) begin
                        seen_held = 1'b1;
                    end
                end
            end else if (prev_rst_n && (req != {N{1'b0}})) begin
                seen_rst = 1'b1;
            end
        end

        if (!rst_n) begin
            for (r = 0; r < N; r = r + 1) begin
                wt[r] = 0;
            end
        end

        // Reference pointer model update.
        if (!rst_n) begin
            mptr = 0;
        end else begin
            for (t = 0; t < N; t = t + 1) begin
                if (eg[t]) begin
                    mptr = (t + 1) % N;
                end
            end
        end

        if (!rst_n) begin
            started = 1'b1;
        end
        prev_req   = req;
        prev_rst_n = rst_n;
        prev_valid = rst_n;

        // End-of-run coverage verdicts.
        if (final_check && !final_done) begin
            final_done = 1'b1;
            if (!seen_none) begin
                $error("rr_arbiter N=%0d: coverage not reached: no requests", N);
                nfail = nfail + 1;
            end else begin
                npass = npass + 1;
            end
            if (!seen_all) begin
                $error("rr_arbiter N=%0d: coverage not reached: everyone requesting", N);
                nfail = nfail + 1;
            end else begin
                npass = npass + 1;
            end
            if (!seen_held) begin
                $error("rr_arbiter N=%0d: coverage not reached: held request among changing others", N);
                nfail = nfail + 1;
            end else begin
                npass = npass + 1;
            end
            if (!seen_long) begin
                $error("rr_arbiter N=%0d: coverage not reached: longest fair wait of N-1 cycles", N);
                nfail = nfail + 1;
            end else begin
                npass = npass + 1;
            end
            if (!seen_rst) begin
                $error("rr_arbiter N=%0d: coverage not reached: reset during traffic", N);
                nfail = nfail + 1;
            end else begin
                npass = npass + 1;
            end
            for (r = 0; r < N; r = r + 1) begin
                if (!seen_alone[r]) begin
                    $error("rr_arbiter N=%0d: coverage not reached: requester %0d alone", N, r);
                    nfail = nfail + 1;
                end else begin
                    npass = npass + 1;
                end
            end
        end
    end

endmodule

module rr_arbiter_tb;

    reg             clk         = 1'b0;
    reg             rst_n       = 1'b0;
    reg  [4:0]      req_all     = 5'b00000;
    reg             final_check = 1'b0;
    wire [31:0]     pass4;
    wire [31:0]     fail4;
    wire [31:0]     pass5;
    wire [31:0]     fail5;
    reg  [8*64-1:0] nonce;
    reg  [31:0]     rnd;
    reg  [4:0]      v;
    integer         passed;
    integer         failed;
    integer         ok;
    integer         seed;
    integer         k;
    integer         r;

    always #5 clk = ~clk;

    rr_arbiter_tb_unit #(.N(4)) u_n4 (
        .clk         (clk),
        .rst_n       (rst_n),
        .req         (req_all[3:0]),
        .final_check (final_check),
        .passed      (pass4),
        .failed      (fail4)
    );

    rr_arbiter_tb_unit #(.N(5)) u_n5 (
        .clk         (clk),
        .rst_n       (rst_n),
        .req         (req_all),
        .final_check (final_check),
        .passed      (pass5),
        .failed      (fail5)
    );

    // Change inputs on the falling edge; the checkers sample on the rising edge.
    task drive(input rv, input [4:0] rq);
        begin
            @(negedge clk);
            rst_n   = rv;
            req_all = rq;
        end
    endtask

    task drive_random(input force_bit2);
        begin
            rnd = $random(seed);
            if (rnd[7:5] == 3'd0) begin
                v = 5'b00000;
            end else if (rnd[7:5] == 3'd1) begin
                v = 5'b11111;
            end else begin
                v = rnd[4:0];
            end
            if (force_bit2) begin
                v = v | 5'b00100;
            end
            drive(1'b1, v);
        end
    endtask

    initial begin
        nonce = {64{8'h00}};
        ok = $value$plusargs("nirmaan_nonce=%s", nonce);
        if (ok == 0) begin
            $display("rr_arbiter_tb: no nirmaan_nonce plusarg given");
        end
        seed = 20261119;

        // Reset, idle; then requests during reset (pointer must stay 0).
        repeat (3) drive(1'b0, 5'b00000);
        repeat (3) drive(1'b0, 5'b11111);
        // No requests.
        repeat (2) drive(1'b1, 5'b00000);
        // Everyone requesting: strict rotation, longest fair wait N-1.
        repeat (12) drive(1'b1, 5'b11111);
        // Each requester alone.
        for (r = 0; r < 5; r = r + 1) begin
            repeat (2) drive(1'b1, 5'b00001 << r);
        end
        // Requester 2 held among changing others.
        for (k = 0; k < 30; k = k + 1) begin
            drive_random(1'b1);
        end
        // Random traffic: drops, raises, idle and full-load cycles.
        for (k = 0; k < 400; k = k + 1) begin
            drive_random(1'b0);
        end
        // Reset during traffic, then rotation from 0 again.
        repeat (3) drive(1'b1, 5'b10110);
        repeat (2) drive(1'b0, 5'b11011);
        repeat (12) drive(1'b1, 5'b11111);
        for (k = 0; k < 100; k = k + 1) begin
            drive_random(1'b0);
        end
        repeat (2) drive(1'b1, 5'b00000);

        // Coverage verdicts, then the run's verdict.
        @(negedge clk);
        final_check = 1'b1;
        @(posedge clk);
        @(negedge clk);
        passed = pass4 + pass5;
        failed = fail4 + fail5;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

`default_nettype wire
=== END FILE ===
